INSERT INTO public.questions (paper_type, question_number, text_mr, text_en, options, correct_option, marks, scoring_rubric, category)
VALUES
('MKMH', 1, 'वयात येण्याची प्रक्रिया ही मुला-मुलींमध्ये एकाच वेळी सुरू होते.', 'The process of puberty triggers at the same time in both boys and girls', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 2, 'स्वप्नावस्था म्हणजे मुलांमध्ये दिसणारे पौगंडावस्थेचे (वयात येण्याचे) एक लक्षण आहे.', '''Wet dreams'' are a symptom of pubertal changes in boys', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 3, 'स्त्रियांमधील दर मासिक चक्रात (पाळीपूर्वी) दोन्ही बीजांडांतून अनेक अंडपेशी बाहेर पडतात.', 'During each menstrual cycle in girls, many ova (ovum) are released from both ovaries', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 4, 'आपल्या आवडत्या व्यक्तीला (मुलगा/मुलगी) संमतीशिवाय वारंवार फोन करणे, हाका मारणे, चिठ्ठी पाठवणे, चावट शेरेबाजी करणे, तिचा पाठलाग करणे किंवा त्या व्यक्तीबद्दल अफवा पसरवणे, हे वर्तन कधीतरी ती व्यक्ती ''पटेल'' म्हणून चालू ठेवणे', 'Calling your crush without his/her consent, calling him/her out in public, sending messages, passing vulgar comments, stalking or spreading rumours about the person is okay, with the hope of future acceptance', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 5, 'मासिक पाळी म्हणजे गर्भाशयाचे नको असलेले अस्तर गळून पडणे', 'Menstrual cycle means shedding of the unwanted lining in uterus', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 6, 'मुलींना कधीच व्यसन लागू शकत नाही', 'Girls never become addicts', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 7, 'फक्त दुय्यम बाह्य लक्षणांवरून (उदा. उंची, आवाज, स्तनांचा आकार इत्यादी) एखाद्या स्त्री/पुरुषाच्या प्रजनन क्षमतेचा अंदाज डॉक्टर १००% सांगू शकतात.', 'Doctors can definitely predict the reproductive ability of a man/woman exclusively based on his/her secondary characteristics', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 8, 'माणसाच्या बाळाचे लिंग गर्भावस्थाच्या सहाव्या महिन्यात निश्चित होते.', 'The sex of the baby is determined during the sixth month of mother''s pregnancy', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 9, 'पौगंडावस्थेमध्ये (वयात येताना) मुला-मुलींमध्ये भावना अतिशय स्थिर व शांत असतात.', 'Children''s emotions are stable and calm during puberty', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 10, 'एच.आय.व्ही.चा विषाणू शरीरातील रोगप्रतिकारक शक्ती नष्ट करतो.', 'HIV destroys the immune system of the body', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 11, 'एकदा दारूचे व्यसन लागले की संपलंच सगळं.', 'Alcohol addiction leads to complete devastation', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 12, 'उगाचच जवळ बसणाऱ्या, अंगाला स्पर्श करणाऱ्या परिचित/अपरिचित व्यक्तीबद्दल आई-वडिलांना सांगणे आवश्यक आहे.', 'A child should communicate to parents about any known/unknown person who unnecessarily tries to become intimate', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 13, 'मासिक पाळीमुळे स्त्री अपवित्र बनते, असे मला वाटते.', 'According to my opinion menstrual cycle makes a woman impure', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 14, 'जीवनात यशस्वी व्हायचे असेल तर केवळ आत्मविश्वास पुरेसा नाही, तर सुंदर दिसणेही आवश्यक आहे.', 'Confidence alone is not enough to be successful in life, looking beautiful/handsome is also equally essential', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 15, 'एखाद्या मुलीने जर तिच्या मित्राला ऐनवेळी नकार दिला आणि तो मुलगा चिडला व त्याने तिच्यावर जबरदस्ती केली, तर त्यात त्याचा काहीच दोष नाही.', 'It is okay if a boy gets angry when a girl refuses his advances for friendship and forces it on her', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 16, 'समलिंगी संबंध ठेवणाऱ्या व्यक्ती माणूस म्हणून सर्व बाबतीत इतरांसारख्याच सक्षम असू शकतात.', 'In all other aspects of life, homosexuals are just like any other human being', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 17, 'खूप पैसा असला ना, की व्यसन-बिसन काही फरक पडत नाही.', 'When you make ample money, addiction just does not make a difference', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 18, 'इंटरनेटवरील इतर सोशल साइट्सवर सहज भेटलेल्या अनोळखी व्यक्तींशी मैत्री करावी, त्यामुळे नवे मित्र-मैत्रिणी मिळतात.', 'One can easily communicate with unknown people on social media sites. In fact you will end up getting more friends.', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 19, 'मुलांना अधिक मैत्रिणी व मुलींना अधिक मित्र असल्यास त्यांचा त्यांच्या गटात भाव वाढतो.', 'Having an opposite gender friend can earn more respect to a boy/girl in their friend circle', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 20, 'अतील कपडे (अंतर्वस्त्रे) कृत्रिम धाग्याने बनवलेली व फॅशनेबल असावीत.', 'Using artificial and attractive undergarments is desirable', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 21, 'बाळ जन्माला येण्यापूर्वी ते मुलगा/मुलगी आहे हे तपासणे त्या पती-पत्नीच्या मर्जीवर अवलंबून आहे.', 'The parents have complete right to decide if they want to check the gender of their baby before birth', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 22, 'मोबाईलवर खूप वेळ गेम खेळणे म्हणजे काही व्यसन नाही.', 'Spending lot of time in playing games on mobile phone can''t be termed as addiction', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 23, 'जननेंद्रियांचा आकार लहान-मोठा असण्यावर लैंगिक क्षमता अवलंबून असते.', 'Sexual capacity of a person depends on the size of the reproductive organs', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 24, 'मुलींनी नाजूक-साजूक दिसावे व मुलांनी कणखर दिसावे, हेच योग्य आहे.', 'Girls should be delicate while boys should be strong', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 25, 'मुलगे व मुली यांच्यात सर्व बाबतीत मुलगेच वरचढ असतात.', 'Boys rock than girls in everything', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 26, 'चांगले वागण्याचे नियम मुला-मुलींसाठी सारखेच असले पाहिजेत.', 'Both boys and girls should have the same set of rules to follow', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 27, 'एखादे व्यसन सुटले की सुटले, परत काही लागत नाही.', 'Once a person is de-addicted, it is for life time', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 28, 'कोणत्याही लांबच्या प्रवासाला मुलींना सोबतीशिवाय पाठवणे योग्य नाही.', 'While traveling long distances, girls should always be accompanied by someone', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 29, 'जड व कष्टाची कामे करावीत तर मुलांनीच.', 'Hard and heavy work is always a man''s job', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 1.00, NULL, 'Adolescent Knowledge & Health'),
('MKMH', 30, 'पुरुषांनी घरातील बारीकसारीक कामे करणे व घर सांभाळणे यात काहीच गैर नाही.', 'It is okay for men to do small household chores and look after the home', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 1.00, NULL, 'Adolescent Knowledge & Health')
INSERT INTO public.questions (paper_type, question_number, text_mr, text_en, options, correct_option, marks, scoring_rubric, category)
VALUES
('MMAT', 1, 'व्यसन हा एक मानसिक आजार आहे', 'Addiction is a psychological disease', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 2, 'सिगारेट प्यायल्यामुळे आपले वजन नियंत्रणात (कंट्रोलमध्ये) राहते.', 'Cigarette smoking helps in weight control', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 3, 'दारू प्यायल्यावर आपले सगळे ताणतणाव (टेन्शन) नाहीसे होतात.', 'Alcohol (liquor) helps in getting rid of all stress and worries', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 4, 'कधीतरी सिगारेट किंवा बिडी ओढली तर त्याचे आपल्यावर काहीच वाईट परिणाम होत नाहीत.', 'There are absolutely no ill effects on health if someone tries cigarette smoking occasionally', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 5, 'सरकारने गुटख्यावर बंदी आणली आहे, त्यामुळे लोक आता गुटखा खात नाहीत.', 'Since government has banned Gutkha (tobacco), no one really consumes it now', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 6, 'इंटरनेट किंवा मोबाईलवरील गेम्स तासन्तास खेळल्यामुळे मेंदूला ताजेतवाने वाटते.', 'The brain gets refreshed when one engages in mobile games for hours together', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 7, 'रोज माशेरी (मिश्री) लावणे याला व्यसन म्हणत नाहीत.', 'Using ''misree'' or ''masheri'' everyday cannot be labeled as addiction', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 8, 'व्यसनी मित्रांच्या संगतीमुळे व्यसनाच्या जाळ्यात अडकले जाऊ शकते.', 'One can get into the trap of addiction due to being friends with those who are addicted to something', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 9, 'मोबाईलचा वापर करता आला नाही म्हणून दुःख होणे किंवा अस्वस्थ वाटणे हे स्वाभाविकच आहे.', 'It is very obvious to become restless/sad if one is not able to use his/her mobile due to some reason', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 10, 'व्यसनी माणसाला एकदा उपचार दिले की ते त्याला निर्व्यसनी व्हायला पुरेसे असतात.', 'Once a person gets therapy for deaddiction, it is enough for keeping the person away from addiction for lifetime', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 11, 'शालेय वयात दर १० मुलांमागे १ मूल व्यसनामध्ये अडकत असते.', 'Every tenth child in schools is getting trapped in addiction of some or the other kind', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 12, 'बुद्धिमान मुलांना व्यसन लागण्याची शक्यता खूप कमी असते.', 'The probability of intelligent people getting addicted to something is too low', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 13, 'एक व्यसनी व्यक्ती स्वतःच्या कमाईचा मोठा भाग व्यसनावर खर्च करते.', 'Any addict spends a huge amount of his/her income on addiction', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 14, 'मुली कधीही व्यसनांमध्ये अडकत नाहीत.', 'Girls never get indulged in addiction', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 15, 'दारू, सिगारेट किंवा तंबाखूपेक्षा इंटरनेट आणि मोबाईलचे व्यसन कमी धोकादायक किंवा नुकसानकारक असते.', 'The addiction to mobile and internet is far less harmful than that of alcohol and tobacco', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 16, 'आपल्या मनात आले की आपण व्यसनावर १००% ताबा लगेच मिळवू शकतो.', 'A person can get 100% control on addiction at once when he/she decides to do so', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 17, 'मोबाईल किंवा कॉम्प्युटरवर अश्लील (पॉर्न) व्हिडिओ पाहिल्यामुळे मानसिक स्वास्थ्य बिघडू शकते.', 'A person can get emotionally/mentally disturbed due to watching porn material on mobile/computer etc', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 18, 'व्यसनामुळे अनेक कुटुंबे उद्ध्वस्त होण्याचे प्रमाण खूप मोठे आहे.', 'The number of families getting completely devastated due to addiction is very huge', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 19, 'गुटखा खाल्ल्यामुळे कधीच कर्करोग (कॅन्सर) होत नाही.', 'Gutkha (tobacco) consumption never leads to cancer', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 20, 'व्यक्ती किती शिकलेली आहे, याचा व्यसनाशी काहीही संबंध नाही.', 'There is no connection between addiction and person''s education', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'CORRECT', 2.00, '{"CORRECT": 2, "WRONG": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 21, 'व्यसनामुळे गरीबांचे जेवढे नुकसान होते, तेवढे श्रीमंतांचे होत नाही.', 'The rich do not face as much loss due to addiction as compared to poor people', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 22, 'ज्या अर्थी चित्रपटांमध्ये दारू, सिगारेट इत्यादी गोष्टी नेहमीच दाखवल्या जातात, त्या अर्थी त्या वाईट गोष्टी नाहीत.', 'As many movies/tele-serials vividly show consumption of cigarette/alcohol on screen, they are definitely not bad things', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 23, 'कायद्याने दारूबंदी केली असता लोक दारूपासून दूर राहतात.', 'When liquor is legally banned, people keep away from it', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 24, 'थोड्या प्रमाणात दारू प्यायली की काम चांगले करता येते आणि कामातील उत्साह वाढतो.', 'Small peg dose of alcohol helps in increasing work efficiency', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 25, 'ड्रग्ज खूप काळ घेत राहिल्यावरच त्यांचे व्यसन लागते.', 'Drug addiction takes place only when one consumes drugs for a prolonged period of time', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 26, 'इतरांना त्रास न देता एखादी व्यक्ती व्यसन करत असेल, तर काही बिघडत नाही.', 'Addiction (alcohol/tobacco/media) which does not trouble other people around is completely harmless', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 27, 'काही अमली (नशिले) पदार्थ घेतल्याने परीक्षेचा अभ्यास चांगला होतो.', 'Consuming addictive drugs helps in better preparation for exams', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 28, 'गंभीर प्रसंगी किंवा तणावाच्या वेळी डोके हलके करण्यासाठी दारू किंवा अमली (नशिले) पदार्थ घेणे आपल्याला मदतच करते.', 'Alcohol or any other such drug is a sure shot help at times of stress/tension provoking moments', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 29, 'दारू, सिगारेट, ड्रग्ज, गुटखा, इंटरनेट यांपैकी कशाचाही परिणाम आपल्या बौद्धिक क्षमतेवर होत नाही.', 'There is absolutely no negative impact of consumption of alcohol/drugs/internet/mobile on our thinking ability', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts'),
('MMAT', 30, 'फेसबुक/इन्स्टाग्राम या ॲप्सचा लोक दुरुपयोग करत नाहीत.', 'People never misuse apps like Facebook, Instagram, WhatsApp, etc.', '[{"code": "CORRECT", "labelMr": "बरोबर", "labelEn": "Correct"}, {"code": "WRONG", "labelMr": "चूक", "labelEn": "Wrong"}, {"code": "DONT_KNOW", "labelMr": "माहीत नाही", "labelEn": "Don''t Know"}]'::jsonb, 'WRONG', 2.00, '{"WRONG": 2, "CORRECT": 1, "DONT_KNOW": 0}'::jsonb, 'Addiction Myths & Facts')
INSERT INTO public.questions (paper_type, question_number, text_mr, text_en, options, correct_option, marks, scoring_rubric, category)
VALUES
('ERT', 1, 'आवडीचा पदार्थ दिसला की तो लगेच खाल्ला पाहिजे असे मला वाटते.', 'I feel like eating my favourite dish as soon as I see it', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 2, 'मित्र-मैत्रिणींनी माझ्या मनाविरुद्ध काही करण्यास सांगितले, तर मी ''नाही'' म्हणू शकतो/शकते.', 'I can refuse, even if my friends ask me to do something against my will', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 3, 'मला राग कंट्रोल होत नाही', 'I cannot control my anger', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 4, 'मित्र-मैत्रिणींनी बोलावले तर मी जे काही करत असेन ते सोडून त्यांच्याबरोबर जावे असे मला वाटते.', 'Whenever my friends call me, I feel like leaving my work and going with them', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 5, 'छोट्या छोट्या गोष्टींमुळे मी अस्वस्थ (डिस्टर्ब) होतो/होते.', 'I get disturbed because of small things', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 6, 'इतरांनी केलेल्या थट्टेमुळे माझा आत्मविश्वास कमी होत नाही.', 'My self confidence does not get affected even if anyone mocks me', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 7, 'अनोळखी व्यक्तींशी बोलताना मला टेन्शन येते.', 'I feel tensed while speaking to strangers', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 8, 'काहीही मनाविरुद्ध घडले की मला टेन्शन येते.', 'I instantly get upset, if something doesn''t happen against my will', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 9, 'एखाद्या कामात अपयश आल्यास त्याचा मला खूप त्रास होतो.', 'It troubles me a lot if I face failure', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 10, 'वैताग येणारी कामे असली तर मी ती सोडून देतो/देते.', 'When I come across any boring task, I tend to give it up', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 11, 'एखादी आवडती गोष्ट नंतर कर असे म्हटले की मला ती लगेच करून बघावीशी वाटते.', 'Whenever I am asked to do my favourite thing later, I feel like doing it right away', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 12, 'माझ्या मते, चांगले न शिकवल्यामुळेच बहुतेक वेळा मुलांना मार्क कमी पडतात.', 'In my opinion, most of the time students get less marks because teachers don''t teach well', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 13, 'माझे मन खूप अस्वस्थ असले तरी मी माझा अभ्यास एकाग्रतेने करू शकतो/शकते.', 'I can concentrate on my studies, even if my mind is restless', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 14, 'एखादे अवघड काम करताना मदत मिळाली नाही तरी मला टेन्शन येते.', 'I get stressed if I don''t get any help while doing a difficult task', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 15, 'चारचौघांमध्ये इतरांपेक्षा वेगळे मत मांडायचे असले तर मला लाज वाटते.', 'I feel shy when I have to express a different opinion than others', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 16, 'बऱ्याच दिवसांपासून ठरलेला बेत अचानक रद्द झाला की मला सहन होत नाही.', 'I can''t stand the sudden cancellation of a plan I had set for many days', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 17, 'मला एखादी गोष्ट हवी असेल तर मी ती काहीही करून मिळवतोच/मिळवतेच.', 'If I want something, I get it by hook or crook', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 18, 'मी इतरांचे मन दुखवत नाही.', 'I don''t hurt feelings of others', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 19, 'माझ्या कुटुंबीयांनी माझे मत ऐकले नाही तर मला खूपच वाईट वाटते.', 'I feel very bad if my family members do not listen to my opinion', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 20, 'पुढे मिळणाऱ्या संधीपेक्षा आत्ता मिळणारे बक्षीस मला जास्त महत्त्वाचे वाटते.', 'For me, the reward I get now is more important than the opportunity I might get in future', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 21, 'घरात वादावादीचे प्रसंग निर्माण झाले तर माझे कशातच लक्ष लागत नाही.', 'Whenever I have an argument at home, I cannot focus on other things', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 22, 'व्यायामाचे महत्त्व कळत असूनसुद्धा सकाळी लवकर उठून व्यायाम करणे मला जमत नाही.', 'In spite of knowing the importance of exercise, I can''t get up early in the morning and do exercise', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 23, 'माझ्या मते, ''लोक काय म्हणतील'' याचा विचार केला पाहिजे.', 'One should always care about what people say', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 24, 'माझ्याकडून चुका झाल्या की मला खूप त्रास होतो.', 'I feel awful when I commit a mistake', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 25, 'वर्गातील मुलीने/मुलाने माझ्याविरुद्ध काही म्हटले तर ते मला सहन होत नाही.', 'I can''t stand if any of my classmates has a word against me', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 26, 'माझ्या मते, जो लकी असतो त्याला यश मिळतेच.', 'In my opinion, lucky people always get success', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 27, 'मला माझ्या नावडत्या विषयांचा अभ्यास करावासाच वाटत नाही.', 'I just don''t feel like studying the subjects that I dislike', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 28, 'रांगेत उभे असताना नंबर लागल्यावर माझे काम अडले की अगदी संताप होतो.', 'I get furious at sudden interruption while standing in the queue', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 29, 'पुढे पुढे करणाऱ्या मुलांनाच वर्गात संधी मिळतात असे मला वाटते.', 'I think only the students who try to please teachers, get opportunities in class', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 30, 'मला न पटणारे मित्र-मैत्रिणींचे बोलणे मी ऐकून घेतो/घेते.', 'I listen to my friends even if their opinions are not in agreement with me', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 31, 'टी.व्ही./मोबाईलवर काही बघत असताना लाईट/नेटवर्क कधीच गेले नाही पाहिजे असे मला वाटते.', 'I feel there should be no power cuts/network disturbances while one watches TV/mobiles', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 32, 'आपण ज्याचा अभ्यास केला नाहीये तेच प्रश्न परीक्षेत आले तर काय, अशी मला भीती वाटते.', 'I fear, what if questions from the syllabus I did not prepare are asked in the exam', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 33, 'मोठ्या माणसांचे एखादे म्हणणे मला पटत नसेल तर तसे मला सांगता येते.', 'I don''t agree with my elders on anything, I can explicitly express it', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 34, 'काही गोष्टी मनासारख्या झाल्या नाहीत तरी फार बिघडत नाही असे मला वाटते.', 'I feel it is okay if somethings don''t happen as I wish', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'ALWAYS', 4.00, '{"ALWAYS": 4, "OFTEN": 3, "SOMETIMES": 2, "NEVER": 1}'::jsonb, 'Emotional Self-Regulation'),
('ERT', 35, 'मला हवे तेव्हा हवी ती वस्तू मिळाली नाही तर मी खूप नाराज होते/होतो.', 'I get very upset if I do not get something when I strongly want it', '[{"code": "ALWAYS", "labelMr": "नेहमी", "labelEn": "Always"}, {"code": "OFTEN", "labelMr": "बऱ्याच वेळा", "labelEn": "Frequently"}, {"code": "SOMETIMES", "labelMr": "कधी कधी", "labelEn": "Sometimes"}, {"code": "NEVER", "labelMr": "कधीच नाही", "labelEn": "Never"}]'::jsonb, 'NEVER', 4.00, '{"NEVER": 4, "SOMETIMES": 3, "OFTEN": 2, "ALWAYS": 1}'::jsonb, 'Emotional Self-Regulation')
