-- ==============================================================================
-- SAIYAM PLATFORM: SEED ALL 95 QUESTIONS & SCORING RUBRICS (FINAL PRODUCTION DATA)
-- Paper 1: MKMH (30 Questions) | Paper 2: MMAT (30 Questions) | Paper 3: ERT (35 Questions)
-- ==============================================================================

-- 1. Ensure required columns exist on public.questions
ALTER TABLE public.questions
ADD COLUMN IF NOT EXISTS marks NUMERIC(5,2) NOT NULL DEFAULT 1.00,
ADD COLUMN IF NOT EXISTS scoring_rubric JSONB DEFAULT NULL;

-- 2. Ensure unique constraint on (paper_type, question_number) for clean upserts
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'unique_paper_question'
    ) THEN
        ALTER TABLE public.questions ADD CONSTRAINT unique_paper_question UNIQUE (paper_type, question_number);
    END IF;
END $$;

-- 3. Enable RLS and grant full permissions
ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all for questions" ON public.questions;
CREATE POLICY "Allow all for questions" ON public.questions FOR ALL USING (true) WITH CHECK (true);
GRANT ALL ON public.questions TO anon, authenticated, service_role;

-- ==============================================================================
