  text_mr = EXCLUDED.text_mr,
  text_en = EXCLUDED.text_en,
  options = EXCLUDED.options,
  correct_option = EXCLUDED.correct_option,
  marks = EXCLUDED.marks,
  scoring_rubric = EXCLUDED.scoring_rubric,
  category = EXCLUDED.category;

